def countRearrangements(s):
    MOD = 10 ** 9 + 7
    fact = [1] * (len(s) + 1)
    for i in range(1, len(s) + 1):
        fact[i] = fact[i - 1] * i % MOD
    cnt = [0] * 26
    for ch in s:
        cnt[ord(ch) - 97] += 1
    result = fact[len(s)]
    for c in cnt:
        result = result * pow(fact[c], MOD - 2, MOD) % MOD
    return result
